INSERT INTO "ai_tutoring_chat" VALUES('60380d4e8e73','5d869f4d6467-1-5','c001',2,'assistant','小朋友，我看到你在第二题里选了B，但题目是“b _ o _”，要补全一个单词哦。你想一想，我们学过的单词里，有没有一个词是b开头、中间有o、结尾还有一个字母的？比如和文具相关的词？','','60380d4e8e73','2026-05-13 15:09:42',NULL);
